/** Complete original sequence/group audit and weighted motif-statistic checks. */
final class HomerGenomeAudit {
    private HomerGenomeAudit() { }
    private static final Pattern COUNTS=Pattern.compile("T:([0-9]+\\.[0-9])\\(([0-9]+\\.[0-9]{2})%\\),B:([0-9]+\\.[0-9])\\(([0-9]+\\.[0-9]{2})%\\),P:1e(-?[0-9]+)");
    record Sequence(HomerGenomeData.Region region,double weight) { }
    record Population(List<Sequence> reversed,double targets,double background) {Population{reversed=List.copyOf(reversed);}}
    static void audit(HomerGenomeData.Data data,HomerGenomeCli.Plan plan,HomerGenomeData.Limits limits,Map<String,String> o,HomerGenomeRuntime.Context runtime,Path work,Map<String,Object> session,List<String> warnings)throws Exception {
        diagnostics(work,runtime.version());
        Path dir=work.resolve("original-out");var required=new ArrayList<>(List.of("seq.tsv","group.adj"));
        if(plan.analysis().known)required.addAll(List.of("knownResults.txt","knownResults.html"));
        else for(String name:List.of("knownResults.txt","knownResults.html"))if(Files.exists(dir.resolve(name)))throw new IOException("Original produced unrequested known enrichment output: "+name);
        if(plan.analysis().discovery)required.addAll(List.of("homerResults.html","homerMotifs.all.motifs","homerMotifs.motifs"+plan.motifWidth()));
        else try(var paths=Files.list(dir)){if(paths.anyMatch(p->p.getFileName().toString().startsWith("homerMotifs.")||p.getFileName().toString().equals("homerResults.html")))throw new IOException("Original produced unrequested de novo discovery output");}
        for(String name:required)if(!Files.isRegularFile(dir.resolve(name)))throw new IOException("Original requested-phase genomic final output missing: "+name);
        var backgroundPositions=new HashMap<String,HomerGenomeData.Region>();var extracted=new HashMap<String,HomerGenomeData.Region>();for(var r:data.regions()){if(r.role().equals("background")&&!r.overlapExcluded())backgroundPositions.put(r.alias(),r);if(!r.overlapExcluded())extracted.put(r.alias(),r);}
        if(o.get("background-mode").equals("supplied")){positions(dir.resolve("bg.clean.pos"),backgroundPositions,false);positions(dir.resolve("target"+(plan.width()==0?"given":Integer.toString(plan.width()))+".pos"),extracted,true);}
        else if(!"passed-complete-native-selected-population".equals(session.get("generated_coordinate_audit")))throw new IOException("Complete generated coordinate/population audit missing");
        var expected=new HashMap<String,HomerGenomeData.Region>();for(var r:data.regions())expected.put(r.alias(),r);var seqOrder=new ArrayList<HomerGenomeData.Region>();var seen=new HashSet<String>();
        try(var in=HomerCoreAudit.reader(dir.resolve("seq.tsv"))){for(String line;(line=HomerCoreAudit.next(in,200010))!=null;){String[] f=line.split("\t",-1);var r=expected.get(f[0]);if(f.length!=2||r==null||!r.sequenceRetained()||!seen.add(f[0])||!r.dna().equals(f[1]))throw new IOException("Original genomic sequence identity,quality exclusion,strand,masking or extraction differs from complete native plan");seqOrder.add(r);}}
        for(var r:data.regions())if(r.sequenceRetained()!=seen.contains(r.alias()))throw new IOException("Original genomic sequence population omitted/added a region: "+r.alias());
        var groups=groups(dir.resolve("group.adj"));var analytic=new HashSet<String>();for(var r:data.regions())if(r.analytic()){analytic.add(r.alias());String[] row=groups.get(r.alias());if(row==null||!row[0].equals(r.role().equals("targets")?"1":"0"))throw new IOException("Original genomic final group role differs from native population plan");}if(!analytic.equals(groups.keySet()))throw new IOException("Original genomic final group population differs from native overlap/quality/frequency-bin plan");
        Map<String,String[]> replay;
        if(plan.norm()>0){var command=new ArrayList<>(List.of(runtime.home().resolve("bin/homer2").toString(),"norm","-s","original-out/seq.tsv","-g","native-pre-normalization.group.tsv","-nlen",Integer.toString(plan.norm()),"-nmax",Integer.toString(plan.iterations()),"-nout","native-plan-normalization.tsv"));if(o.get("strands").equals("forward"))command.addAll(List.of("-strand","+"));int exit=HomerRuntime.executeCommand(command,work,"normalization-replay",limits.timeout(),limits.workspace(),limits.rss(),Map.of("PATH",runtime.home().resolve("bin")+":/usr/bin:/bin"),runtime::verify,()->{if(!runtime.markerHash().equals(FollowupSupport.hash(runtime.home().resolve(".jlinalg-homer-genome.json"))))throw new IOException("Genomic runtime marker changed");},session);if(exit!=0)throw new IOException("Original oligonucleotide normalization replay failed;inspect normalization-replay.stderr");replay=groups(work.resolve("normalization-replay.stdout"));}
        else replay=groups(work.resolve("native-pre-normalization.group.tsv"));
        if(!replay.keySet().equals(groups.keySet()))throw new IOException("Native-plan original normalization replay changes population");for(var e:groups.entrySet()){String[] a=e.getValue(),b=replay.get(e.getKey());if(!a[0].equals(b[0])||Math.abs(value(a[1])-value(b[1]))>2e-6+1e-9*Math.abs(value(a[1])))throw new IOException("Original normalized weight differs from independent replay of native initial weights");}
        var reversed=new ArrayList<Sequence>();double targets=0,background=0;for(int i=seqOrder.size()-1;i>=0;i--){var r=seqOrder.get(i);if(!groups.containsKey(r.alias()))continue;double w=value(groups.get(r.alias())[1]);reversed.add(new Sequence(r,w));if(r.role().equals("targets"))targets+=w;else background+=w;}
        var population=new Population(reversed,targets,background);test(targets,0,background,0,o.get("statistic"));
        var budget=new HomerCoreData.Budget(limits.workspace());try(var walk=Files.walk(work)){for(var path:walk.filter(Files::isRegularFile).toList())budget.add(Files.size(path));}
        try(var ledger=budget.writer(work.resolve("population.tsv"))){ledger.write("original_runtime_id\trole\tsource_ordinal\tdisposition\tpre_oligo_weight\toriginal_final_weight\tsequence_retained\tstatistical_population_member\n");for(var r:data.regions())ledger.write(r.alias()+"\t"+r.role()+"\t"+r.ordinal()+"\t"+r.disposition()+"\t"+r.preWeight()+"\t"+(groups.containsKey(r.alias())?groups.get(r.alias())[1]:"NA")+"\t"+r.sequenceRetained()+"\t"+r.analytic()+"\n");}
        Long known=plan.analysis().known?known(data,population,o,runtime.version(),dir,work,budget):null,learned=plan.analysis().discovery?discovery(data,population,plan,o,dir,work,budget,session):null;
        session.put("known_analysis",plan.analysis().known?"completed":"not-requested");session.put("discovery_analysis",plan.analysis().discovery?"completed":"not-requested");session.put("known_motifs",known);session.put("learned_motifs",learned);session.put("retained_original_sequences",seqOrder.size());session.put("analytic_records",reversed.size());session.put("original_weighted_target_population",targets);session.put("original_weighted_background_population",background);session.put("original_statistic_floored_target_population",(int)targets);session.put("original_statistic_floored_background_population",(int)background);session.put("normalization_audit",plan.norm()>0?"original-engine-independent-native-input-replay":"none-explicit-native-weights");session.put("native_audit_operation_bound",data.operations());session.put("conservative_upstream_memory_estimate",data.upstreamEstimate());
        warnings.add("STATISTICAL POPULATION REVIEW: original weights sum to targets="+targets+",background="+background+". Original EnrichmentScorer floors weighted totals and weighted motif-presence counts to unsigned integers before the specified binomial/hypergeometric test;native results preserve both weighted values and discrete test inputs. Source accumulation order is retained because flooring near an integer is order-sensitive. Original displayed totals may be inferred from rounded counts/percentages and are not authoritative population sizes. Required action: inspect population.tsv,the requested-phase result tables and the recorded weighted/floored totals;these tests do not establish calibrated inference for an arbitrary weighted sampling design.");
        if(plan.analysis().known)warnings.add("ORIGINAL Q-VALUE REVIEW: the source Statistics::benjaminiFDR exponentiates its six-decimal intermediate logP,sorts P values,groups ties at the last rank and takes a forward cumulative maximum of m*p/rank,clipped at1. This differs from the reverse cumulative minimum used by standard Benjamini-Hochberg. original_q is preserved beside a native reconstruction of the actual original algorithm;it is not relabelled as standard BH. original_coarse_p uses HOMER's truncated decimal exponent and is not a precise P value. Required action: review the complete known-motif family and select any downstream multiple-testing procedure explicitly;retain full native log P and original values separately.");
        warnings.add("NORMALIZATION REVIEW: native Java checks extraction,all input dispositions and GC/CpG bins/initial weights. Oligonucleotide-normalized weights are original-engine values checked by an independent replay from native initial weights and the retained exact sequence order. Required action: inspect population.tsv and normalization_audit in session.json;this does not establish a weighted sampling model or reconstruct normalization natively.");
        if(plan.analysis().discovery)warnings.add("DISCOVERY REVIEW: learned models use conservative +/-0.0081 cell and +/-0.000000501 threshold bounds to retain uncertainty from original print-time transformations. Required action: inspect discovery-results.tsv and discovery-presence.tsv;compatible bounds are not a reconstruction of the optimizer's internal full-precision model. Similarity-to-known scores are not P/q/E values.");
        if(learned!=null&&learned==0)warnings.add("NO DISCOVERED MOTIFS: original finalized with an empty discovered family. Required action: review the supplied contrast,canonical windows and original diagnostics;this does not prove absence of regulatory signal.");
    }
    static void diagnostics(Path work,String version)throws IOException{
        String stderr=Files.readString(work.resolve("original.stderr"));
        if(stderr.contains("Illegal division by zero")&&stderr.contains("findKnownMotifs.pl"))throw new IOException("Original HOMER "+version+" known-report failure: Illegal division by zero in findKnownMotifs.pl. The original report infers population sizes from a motif's rounded hit percentages and can divide by zero at zero percent;its outer wrapper may still exit0. Required action: retain the failed analysis and inspect original.stderr,inputs and models. Select any scientifically appropriate separately admitted version or operation explicitly before rerunning to NEW paths;no automatic version substitution or source patch is applied");
        for(String bad:List.of("HOMER not configured","not found","Wrong file format","Could not open","Can't open","uninitialized","Illegal division","ERROR IN TREE","Out of room in oligo TREE","Ran out of room for more oligos","X is not right in betai"))if(stderr.contains(bad))throw new IOException("Original genomic diagnostic reported a failure: "+bad);
        if(Pattern.compile("(?i)(?<![A-Za-z])(?:nan|[+-]?inf)(?![A-Za-z])").matcher(stderr).find())throw new IOException("Original genomic diagnostics contain nonfinite arithmetic");
        if(!stderr.contains("Finished preparing sequence/group files")||!stderr.contains("Job finished"))throw new IOException("Original genomic wrapper did not finalize;zero exit alone is insufficient");
    }
    static void positions(Path path,Map<String,HomerGenomeData.Region> expected,boolean extraction)throws Exception{
        var seen=new HashSet<String>();try(var in=HomerCoreAudit.reader(path)){for(String line;(line=HomerCoreAudit.next(in,1048576))!=null;){if(line.isBlank()||line.startsWith("#"))continue;String[] f=line.split("\t",-1);var r=expected.get(f[0]);if(f.length<5||r==null||!seen.add(f[0]))throw new IOException("Original genomic position population differs from complete native plan");var p=extraction?r.extraction():r.original();if(!f[1].equals(r.contig())||!f[2].equals(Long.toString(p.start1()))||!f[3].equals(Long.toString(p.end1()))||!f[4].equals(Character.toString(p.strand())))throw new IOException("Original genomic position/strand differs from native exact coordinate plan");}}if(!seen.equals(expected.keySet()))throw new IOException("Original genomic positions omitted planned regions");
    }
    static Map<String,String[]> groups(Path path)throws Exception{var result=new HashMap<String,String[]>();try(var in=HomerCoreAudit.reader(path)){for(String line;(line=HomerCoreAudit.next(in,1024))!=null;){String[] f=line.split("\t",-1);if(f.length<2||f.length>3||!List.of("0","1").contains(f[1])||result.containsKey(f[0]))throw new IOException("Malformed/duplicate original group row");String weight=f.length==3?f[2]:"1";if(value(weight)<0)throw new IOException("Negative original group weight");result.put(f[0],new String[]{f[1],weight});}}return result;}
    static HomerEnrichment.Result test(double nt,double t,double nb,double b,String statistic)throws IOException{
        for(double x:new double[]{nt,t,nb,b})if(!Double.isFinite(x)||x<0||x>Integer.MAX_VALUE)throw new IOException("Nonfinite,negative or excessive original weighted population");if(t>nt+1e-8||b>nb+1e-8||(long)(int)nt+(int)nb>Integer.MAX_VALUE)throw new IOException("Invalid original weighted motif counts");
        try{return HomerEnrichment.test(new HomerEnrichment.Counts((int)nt,(int)t,(int)nb,(int)b),statistic.equals("binomial")?HomerEnrichment.Statistic.BINOMIAL:HomerEnrichment.Statistic.HYPERGEOMETRIC);}catch(IllegalArgumentException failure){throw new IOException("Original floored statistical population is degenerate;review the retained weights",failure);}
    }
    private static long known(HomerGenomeData.Data data,Population pop,Map<String,String> o,String version,Path dir,Path work,HomerCoreData.Budget budget)throws Exception{
        var byAlias=new HashMap<String,HomerGenomeData.Model>();for(var m:data.known())byAlias.put(m.alias(),m);var computed=new HashMap<String,double[]>();double[] pvalues=new double[data.known().size()];var strands=HomerGenomeCli.knownStrands(o,version);
        for(var model:data.known()){double t=0,b=0;var compiled=new HomerGenomeMatrices.Scorer(model.motif());for(var s:pop.reversed){if(compiled.present(s.region.dna(),strands)){if(s.region.role().equals("targets"))t+=s.weight;else b+=s.weight;}}var result=test(pop.targets,t,pop.background,b,o.get("statistic"));computed.put(model.alias(),new double[]{t,b,result.logP()});pvalues[model.motif().ordinal()-1]=Math.exp(sourcePrintedLogP(result.logP()));}
        double[] originalAdjustment=forwardAdjustment(pvalues);var seen=new HashSet<String>();long rows=0;
        try(var in=HomerCoreAudit.reader(dir.resolve("knownResults.txt"));var out=budget.writer(work.resolve("results.tsv"))){String header=HomerCoreAudit.next(in,4096);if(header==null||!header.startsWith("Motif Name\tConsensus\tP-value\tLog P-value\tq-value (Benjamini)\t"))throw new IOException("Original known genomic table header differs");out.write("known_alias\tsource_ordinal\tname_json\toriginal_consensus\toriginal_coarse_p\toriginal_log_p_rounded\toriginal_q\toriginal_target_count_rounded\toriginal_target_percent\toriginal_background_count_rounded\toriginal_background_percent\tnative_weighted_target_with_motif\tnative_weighted_background_with_motif\tnative_log_p\tnative_original_forward_q\n");double previous=Double.NEGATIVE_INFINITY;
            for(String line;(line=HomerCoreAudit.next(in,8192))!=null;){String[] f=line.split("\t",-1);if(f.length!=9||!byAlias.containsKey(f[0])||!seen.add(f[0]))throw new IOException("Original known table has unknown/duplicate motif or malformed fields");var model=byAlias.get(f[0]);double[] values=computed.get(f[0]);var result=test(pop.targets,values[0],pop.background,values[1],o.get("statistic"));rounded(value(f[5]),values[0],.050001,"known target presence");rounded(value(f[7]),values[1],.050001,"known background presence");percent(f[6],100*values[0]/pop.targets);percent(f[8],100*values[1]/pop.background);double lp=value(f[3]);rounded(lp,result.logP(),scientificTolerance(f[3]),"known log P");if(lp<previous)throw new IOException("Original known family logP order differs");previous=lp;if(!f[2].equals("1e"+result.originalDisplayExponent()))throw new IOException("Original known coarse P differs");double q=value(f[4]),nativeQ=originalAdjustment[model.motif().ordinal()-1];rounded(q,nativeQ,.0000501,"original forward q adjustment");out.write(f[0]+"\t"+model.motif().ordinal()+"\t"+RegenieRuntime.json(model.motif().name())+"\t"+String.join("\t",Arrays.copyOfRange(f,1,9))+"\t"+values[0]+"\t"+values[1]+"\t"+values[2]+"\t"+nativeQ+"\n");rows++;}
        }if(rows!=data.known().size())throw new IOException("Original known table omitted supplied motif models");return rows;
    }
    static double[] forwardAdjustment(double[] input){var order=new Integer[input.length];for(int i=0;i<order.length;i++){if(!Double.isFinite(input[i])||input[i]<0||input[i]>1)throw new IllegalArgumentException("Require finite P values in[0,1]");order[i]=i;}Arrays.sort(order,java.util.Comparator.comparingDouble(i->input[i]));var result=new double[input.length];double last=-1e10;int prior=-1;for(int i=0;i<order.length;i++){if(i+1<order.length&&input[order[i+1]]==input[order[i]])continue;double q=Math.min(1,Math.max(last,input[order[i]]*input.length/(i+1)));for(int j=i;j>prior;j--)result[order[j]]=q;last=q;prior=i;}return result;}
    private static long discovery(HomerGenomeData.Data data,Population pop,HomerGenomeCli.Plan plan,Map<String,String> o,Path dir,Path work,HomerCoreData.Budget budget,Map<String,Object> session)throws Exception {
        Path source=dir.resolve("homerMotifs.motifs"+plan.motifWidth());var models=Files.size(source)==0?List.<HomerMotifs.Motif>of():HomerMotifs.read(source,new HomerMotifs.Limits(plan.motifs(),plan.motifWidth(),(long)plan.motifs()*plan.motifWidth(),10000000,10000000,1048576));long uncertain=0;
        var strands=o.get("strands").equals("both")?HomerMotifs.Strands.BOTH:HomerMotifs.Strands.FORWARD;
        try(var out=budget.writer(work.resolve("discovery-results.tsv"));var ledger=budget.writer(work.resolve("discovery-presence.tsv"))){out.write("motif_ordinal\tname_json\toriginal_log_p\toriginal_count_metadata\tdefinite_weighted_target\tpossible_weighted_target\tdefinite_weighted_background\tpossible_weighted_background\tnative_min_logp\tnative_max_logp\n");ledger.write("motif_ordinal\toriginal_runtime_id\trole\tweight\tdefinite_presence\tpossible_presence\tprinted_model_presence\n");for(var m:models){if(m.width()!=plan.motifWidth()||m.sourceLogP()==null||m.extraHeader().size()<2)throw new IOException("Original learned motif schema differs");var metadata=COUNTS.matcher(m.extraHeader().get(1));if(!metadata.matches())throw new IOException("Malformed original learned weighted count metadata");var envelope=HomerDiscoveryIntervals.compile(m);double[] definite={0,0},possible={0,0};for(var s:pop.reversed){var summary=HomerDiscoveryIntervals.scan(s.region.dna(),envelope,strands);int role=s.region.role().equals("targets")?0:1;if(summary.definitePresence())definite[role]+=s.weight;if(summary.possiblePresence())possible[role]+=s.weight;ledger.write(m.ordinal()+"\t"+s.region.alias()+"\t"+s.region.role()+"\t"+s.weight+"\t"+summary.definitePresence()+"\t"+summary.possiblePresence()+"\t"+(summary.nominalSites()>0)+"\n");}
                double t=value(metadata.group(1)),b=value(metadata.group(3));if(t<definite[0]-.050001||t>possible[0]+.050001||b<definite[1]-.050001||b>possible[1]+.050001)throw new IOException("Learned motif weighted presence lies outside conservative native precision bounds");percentRange(value(metadata.group(2)),100*definite[0]/pop.targets,100*possible[0]/pop.targets);percentRange(value(metadata.group(4)),100*definite[1]/pop.background,100*possible[1]/pop.background);double min=test(pop.targets,possible[0],pop.background,definite[1],o.get("statistic")).logP(),max=test(pop.targets,definite[0],pop.background,possible[1],o.get("statistic")).logP();if(m.sourceLogP()<min-.000002||m.sourceLogP()>max+.000002)throw new IOException("Original learned log P outside native weighted-presence statistical bounds");if(definite[0]!=possible[0]||definite[1]!=possible[1])uncertain++;out.write(m.ordinal()+"\t"+RegenieRuntime.json(m.name())+"\t"+m.sourceLogP()+"\t"+m.extraHeader().get(1)+"\t"+definite[0]+"\t"+possible[0]+"\t"+definite[1]+"\t"+possible[1]+"\t"+min+"\t"+max+"\n");}
        }session.put("learned_models_with_presence_uncertainty",uncertain);if(!models.isEmpty()){try(var files=Files.walk(dir.resolve("homerResults"))){if(files.noneMatch(p->p.toString().endsWith(".svg")&&Files.isRegularFile(p)))throw new IOException("Original learned motif SVG report missing");}}return models.size();
    }
    static double value(String s)throws IOException{return HomerGenomeCli.number(s,-Double.MAX_VALUE,Double.MAX_VALUE);}
    private static void rounded(double actual,double expected,double tolerance,String label)throws IOException{if(Math.abs(actual-expected)>tolerance+1e-9*Math.abs(expected))throw new IOException("Original "+label+" differs from complete native audit: "+actual+" vs "+expected);}
    private static void percent(String text,double expected)throws IOException{if(!text.endsWith("%"))throw new IOException("Original percentage suffix missing");rounded(value(text.substring(0,text.length()-1)),expected,.005001,"percentage");}
    private static void percentRange(double actual,double min,double max)throws IOException{if(actual<min-.005001||actual>max+.005001)throw new IOException("Original learned percentage outside native precision bounds");}
    static double scientificTolerance(String text)throws IOException{if(value(text)==0)return .000000501;int i=Math.max(text.indexOf('e'),text.indexOf('E'));if(i<0)throw new IOException("Original known logP scientific format changed");try{return .000501*Math.pow(10,Integer.parseInt(text.substring(i+1)))+.000000501;}catch(NumberFormatException failure){throw new IOException("Invalid scientific logP",failure);}}
    static double sourcePrintedLogP(double value){double rounded=new java.math.BigDecimal(value).setScale(6,java.math.RoundingMode.HALF_EVEN).doubleValue();return rounded==0?Math.copySign(0.0,value):rounded;}

}
